import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/EN.P9aPnFBv.js";import{_ as t}from"./chunks/DIS.DdpTdGGD.js";import{_ as s,o as i,c as n,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const x=JSON.parse('{"title":"Paramètres Bluetooth","description":"","frontmatter":{"source_hash":"c7d2a497a5","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/bluetooth.md","filePath":"fr/use/bluetooth.md"}'),l={name:"fr/use/bluetooth.md"};function c(u,o,p,d,m,h){return i(),n("div",null,[...o[0]||(o[0]=[r('<p>La multitude de fabricants de téléphones Android et les particularités des capteurs et transmetteurs font de la fiabilité de la connexion Bluetooth une difficulté majeure pour xDrip. Ce menu contient de nombreux réglages avancés qui ne peuvent pas être standardisés pour tous les systèmes.</p><div class="info custom-block"><p class="custom-block-title">Configurez les paramètres Bluetooth comme indiqué ci-dessous</p></div><p>Une approche par essais successifs est recommandée, mais ne modifiez qu&#39;un paramètre à la fois pour éviter d&#39;ajouter de la confusion.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  Paramètres moins courants<br>   <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_bluetooth_settings_grey600_48dp.png" style="width:5%;"> Paramètres Bluetooth</p></div><h4 id="turn-bluetooth-on" tabindex="-1">Activer le Bluetooth <a class="header-anchor" href="#turn-bluetooth-on" aria-label="Permalink to &quot;Activer le Bluetooth {#turn-bluetooth-on}&quot;">​</a></h4><p>Cette option fait que xDrip essaie d&#39;activer le Bluetooth.</p><p>Si xDrip se connecte à un appareil Bluetooth, Activer le Bluetooth est indispensable.<br> xDrip peut ne pas réussir à passer outre complètement les réglages de votre téléphone : si vous désactivez le Bluetooth dans les paramètres Android ou mettez votre téléphone en mode avion, il risque de ne pas pouvoir le réactiver. Le Bluetooth doit être activé dans les paramètres Android si vous voulez que xDrip l&#39;utilise.</p><p><em>Collecteur : gestion Bluetooth globale (transmetteur classique + OB1 Dex) — Dexcom G5/G6/G7, transmetteurs G4/Libre</em></p><div class="admonition xdripitem"><p class="admonition-title">Activer le Bluetooth<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Activer automatiquement bluetooth s&#39;il est éteint lorsqu&#39;on tente de se connecter à un périphérique bluetooth</p></div><h4 id="bluetooth-watchdog" tabindex="-1">Garde-fou Bluetooth <a class="header-anchor" href="#bluetooth-watchdog" aria-label="Permalink to &quot;Garde-fou Bluetooth {#bluetooth-watchdog}&quot;">​</a></h4><p>En cas de données manquantes à cause d&#39;une perte de connexion Bluetooth, vous pouvez faire en sorte que xDrip désactive puis réactive le Bluetooth de votre téléphone ; le délai par défaut est de 20 minutes sans données. Vous pouvez personnaliser cette valeur.</p><p>Si vous voyez le message indiquant que <strong>xDrip a désactivé le Bluetooth</strong>, c&#39;est probablement parce que le garde-fou s&#39;est déclenché et que xDrip essaie de rétablir la connexion avec le capteur.</p><p><em>Collecteur : logique de récupération globale (collecteurs classiques + séquenceur) — collecteurs Dexcom et à transmetteur</em></p><div class="admonition xdripitem"><p class="admonition-title">Garde-fou Bluetooth<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Réinitialiser Bluetooth en le désactivant puis réactivant si nous n’obtenons rien pendant 20 minutes</p></div><p>Lorsque le garde-fou est activé, vous pouvez choisir au bout de combien de temps sans données il se déclenche : 20 (par défaut), 15, 10 ou 5 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Délai pour le garde-fou BT</p><p> Saisir la valeur en minutes</p></div><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>Attention : le déclenchement du garde-fou Bluetooth entraîne une déconnexion Bluetooth temporaire de tous les appareils connectés. Vous voudrez peut-être désactiver cette fonction si vous utilisez AAPS et que votre transmetteur ou votre pompe ne rétablit pas automatiquement la connexion Bluetooth.<br> Notez que le collecteur Dexcom (G5/G6/G7/ONE/ONE+/Stelo) possède son propre garde-fou Bluetooth, toujours actif et non contrôlé par ce paramètre (le paramètre Chien de garde Bluetooth Dex a été supprimé dans la version <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.04.22" target="_blank" rel="noreferrer">2026.04.22</a>).</p></div><h4 id="close-gatt-on-ble-disconnect" tabindex="-1">Fermer GATT sur déconnexion BLE <a class="header-anchor" href="#close-gatt-on-ble-disconnect" aria-label="Permalink to &quot;Fermer GATT sur déconnexion BLE {#close-gatt-on-ble-disconnect}&quot;">​</a></h4><p>Lorsque cette option est activée, xDrip effectue une déconnexion complète puis une reconnexion de votre appareil Bluetooth (fermeture du lien, découverte et connexion) en cas de perte de connexion. Comme cela peut être inefficace, il est recommandé de la laisser <strong>désactivée</strong> : l&#39;appareil reste alors en mémoire et xDrip essaie seulement de s&#39;y reconnecter en tant qu&#39;appareil BLE connu.</p><p><em>Collecteur : collecteur de transmetteur classique (<code>DexCollectionService</code>) — transmetteurs G4/Libre, BlueReader/Atom/Tomato</em></p><div class="admonition xdripitem"><p class="admonition-title">Fermer GATT sur déconnexion BLE<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Si le garde-fou Bluetooth s&#39;active souvent alors vous pouvez essayer de décocher cette option pour voir si ça aide</p></div><h4 id="use-scanning" tabindex="-1">Utiliser le scan <a class="header-anchor" href="#use-scanning" aria-label="Permalink to &quot;Utiliser le scan {#use-scanning}&quot;">​</a></h4><p>Utiliser le scan effectue l&#39;équivalent de Scan Bluetooth du menu principal pour tenter de rétablir une connexion perdue. Ce n&#39;est pas toujours efficace avec les téléphones récents. Laissez-la d&#39;abord <strong>désactivée</strong>, sauf si elle s&#39;avère utile.</p><p><em>Collecteur : collecteur de transmetteur classique (<code>DexCollectionService</code>) — transmetteurs G4/Libre, BluKon</em></p><div class="admonition xdripitem"><p class="admonition-title">Utiliser le scan<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Scanner avant de se connecter sur xBridge et Bluetooth Libre</p></div><h4 id="use-ble-manager" tabindex="-1">Use BLE manager <a class="header-anchor" href="#use-ble-manager" aria-label="Permalink to &quot;Use BLE manager {#use-ble-manager}&quot;">​</a></h4><p>Utilise un système de gestion BLE plus moderne. Laissez-la <strong>désactivée</strong>, sauf si vous dépannez un problème de connexion et qu&#39;on vous a conseillé de l&#39;essayer.</p><p><em>Collecteur : collecteur de transmetteur classique (<code>DexCollectionService</code>) — appareils à transmetteur</em></p><div class="admonition xdripitem"><p class="admonition-title">Use BLE manager<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Use a more modern BLE manager system (utiliser un système de gestion BLE plus moderne)</p></div><h4 id="trust-auto-connect" tabindex="-1">Faire confiance à Auto-Connect <a class="header-anchor" href="#trust-auto-connect" aria-label="Permalink to &quot;Faire confiance à Auto-Connect {#trust-auto-connect}&quot;">​</a></h4><p>Faire confiance à Auto-Connect dépend vraiment de votre téléphone. Cette option est <strong>activée</strong> par défaut. Si vous avez un Samsung, Xiaomi, OnePlus, Oppo, Huawei ou Realme, vous devriez probablement la désactiver. Si vous perdez souvent la connexion sans parvenir à la rétablir, essayez de la désactiver.</p><p><em>Collecteur : collecteur de transmetteur classique + collecteur OB1 Dex — Dexcom G5/G6/G7, appareils à transmetteur</em></p><div class="admonition xdripitem"><p class="admonition-title">Faire confiance à Auto-Connect<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Utiliser et faire confiance à la fonctionnalité de connexion auto Bluetooth d&#39;Android</p></div><h4 id="use-background-scan" tabindex="-1">Utiliser les scans en arrière-plan <a class="header-anchor" href="#use-background-scan" aria-label="Permalink to &quot;Utiliser les scans en arrière-plan {#use-background-scan}&quot;">​</a></h4><p>Utiliser les scans en arrière-plan est une fonction des versions récentes d&#39;Android, <strong>activée</strong> par défaut. Si vous perdez régulièrement la connexion, essayez de la désactiver.</p><p><em>Collecteur : collecteurs à séquenceur/scan en arrière-plan (Android O+) — principalement collecteurs Dexcom/BLE</em></p><div class="admonition xdripitem"><p class="admonition-title">Utiliser les scans en arrière-plan<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Utiliser la fonction de scan en arrière-plan d&#39;Android 8+</p></div><h4 id="companion-bluetooth" tabindex="-1">Companion Bluetooth <a class="header-anchor" href="#companion-bluetooth" aria-label="Permalink to &quot;Companion Bluetooth {#companion-bluetooth}&quot;">​</a></h4><p>Companion Bluetooth permet à l&#39;application de fonctionner en même temps que l&#39;application Dex principale connectée au capteur.</p><p><em>Collecteur : écouteur compagnon BlueTails — émetteurs Dexcom en configuration compagnon/sniffer</em></p><div class="admonition xdripitem"><p class="admonition-title">Companion Bluetooth<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Use Bluetooth with companion app data source (utiliser le Bluetooth avec la source de données application compagnon)</p></div><h4 id="bluetooth-wakelocks" tabindex="-1">Wakelocks Bluetooth <a class="header-anchor" href="#bluetooth-wakelocks" aria-label="Permalink to &quot;Wakelocks Bluetooth {#bluetooth-wakelocks}&quot;">​</a></h4><p>Les wakelocks Bluetooth ne sont pas recommandés et doivent rester <strong>désactivés</strong>.</p><p><em>Collecteur : collecteur classique + chemins de callback BLE — principalement collecteurs à transmetteur</em></p><div class="admonition xdripitem"><p class="admonition-title">Wakelocks Bluetooth<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Anciens wakelocks Bluetooth qui peuvent drainer la batterie un peu plus, mais pourraient être nécessaire pour la réception bluetooth</p></div><h4 id="xbridge-polling-mode" tabindex="-1">Mode de sondage xBridge+ <a class="header-anchor" href="#xbridge-polling-mode" aria-label="Permalink to &quot;Mode de sondage xBridge+ {#xbridge-polling-mode}&quot;">​</a></h4><p>Le mode de sondage xBridge+ permet à xDrip d&#39;envoyer des requêtes au transmetteur. Même s&#39;il n&#39;a aucun effet avec les autres appareils Bluetooth, vous pouvez l&#39;activer si vous perdez souvent la connexion, car il occupera de toute façon le Bluetooth de votre téléphone à essayer de se connecter.</p><p><em>Collecteur : collecteur de transmetteur classique (<code>DexCollectionService</code>) — xBridge et matériels similaires</em></p><div class="admonition xdripitem"><p class="admonition-title">Mode de sondage xBridge+<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Support expérimental pour la fonction de sondage xBridge+</p></div><h4 id="always-discover-services" tabindex="-1">Toujours découvrir les services <a class="header-anchor" href="#always-discover-services" aria-label="Permalink to &quot;Toujours découvrir les services {#always-discover-services}&quot;">​</a></h4><p>Activé par défaut. Visible uniquement lorsque l&#39;Engineering mode (Mode développeur) est activé.</p><p><em>Collecteur : collecteur de transmetteur classique (<code>DexCollectionService</code>) — appareils BLE à transmetteur</em></p><div class="admonition xdripitem"><p class="admonition-title">Toujours découvrir les services<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Sonder les services Bluetooth à chaque connexion</p></div><h4 id="use-gatt-refresh" tabindex="-1">Use GATT refresh <a class="header-anchor" href="#use-gatt-refresh" aria-label="Permalink to &quot;Use GATT refresh {#use-gatt-refresh}&quot;">​</a></h4><p>Indique s&#39;il faut utiliser le mécanisme bas niveau de rafraîchissement GATT. Activé par défaut. Visible uniquement lorsque l&#39;Engineering mode (Mode développeur) est activé.</p><p><em>Collecteur : collecteur OB1 Dex, collecteurs de type JamBase — Dexcom G5/G6/G7, Medtrum</em></p><div class="admonition xdripitem"><p class="admonition-title">Use GATT refresh<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Whether to use the low level gatt refresh mechanism (utiliser ou non le mécanisme bas niveau de rafraîchissement GATT)</p></div><h4 id="allow-blucon-unbonding" tabindex="-1">Permettre la dissociation du BluCon <a class="header-anchor" href="#allow-blucon-unbonding" aria-label="Permalink to &quot;Permettre la dissociation du BluCon {#allow-blucon-unbonding}&quot;">​</a></h4><p>Permettre la dissociation du BluCon n&#39;est utile que si vous utilisez un transmetteur BluCon, car les autres ne s&#39;associent pas à votre téléphone. Si ce transmetteur vous demande souvent l&#39;association, désactivez cette option.</p><p><em>Collecteur : chemin des transmetteurs BluKon/Libre — BluKon et configurations de transmetteurs Libre apparentées</em></p><div class="admonition xdripitem"><p class="admonition-title">Permettre la dissociation du BluCon<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Disponible uniquement pour les téléphones qui supportent l&#39;association automatique</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',63)])])}const B=s(l,[["render",c]]);export{x as __pageData,B as default};
